        engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Exceptionally lightweight, optimizing the 50:50 weight distribution of the 1 Series chassis. It lacks the complex Valvetronic system, relying purely on direct injection for efficiency.", crankshaft: "Cast Iron, supported by 5 main bearings, optimized for low rotational mass.", pistonSpeed: "14.4 m/s @ 6000 RPM.", alternator: "110A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with heavily specialized asymmetrical crowns designed strictly for the direct injection stratified lean-burn combustion process.", wristPinDiameter: "20 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "56.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.77." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the massive 12.0:1 compression ratio.", intakePortFlow: "High-velocity tumble ports designed specifically to mix air with the high-pressure fuel spray. Severely prone to carbon choking.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Double VANOS (Variable Valve Timing) on both intake and exhaust camshafts.", lifterType: "Hydraulic lifters with roller finger followers.", specialFeature: "Direct injection ports directly inside the combustion chamber, entirely bypassing the intake valves." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "105°C Map-controlled electronic thermostat for extreme thermal efficiency.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar generated by the mechanical HPFP.", injectors: "4x Siemens VDO Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm.", maxSafePowerStock: "180 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Piezo Injectors, Plastic Timing Chain Guides, NOX System." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Siemens MSD81.2." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to save the highly fragile N43 block from premature destruction.", parts: [ { category: "Piezo Injectors", brand: "Genuine BMW (Index 11)", note: "CRITICAL: The only permanent cure for the N43's catastrophic misfires." }, { category: "NOX Emulator", brand: "BimmerProfs NOXEM", note: "CRITICAL: Bypasses the failing factory NOX system completely." }, { category: "Timing Chain Kit", brand: "Febi / INA", note: "Must be replaced entirely if rattling or plastic guide wear is detected." }, { category: "High Pressure Fuel Pump", brand: "Genuine BMW", note: "Replace if long cranking times or limp mode occur under acceleration." }, { category: "Ignition Coils", brand: "Bosch / Delphi", note: "Upgrade to the latest revision for reliable cold starts." }, { category: "Spark Plugs", brand: "NGK Laser Platinum", note: "Replace strictly every 40k km; the lean-burn system destroys plugs." }, { category: "Valve Cover Gasket", brand: "Elring", note: "Replace if oil is found leaking into the spark plug tubes." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use exclusively OEM quality filters to protect the VANOS system." } ] },
