          fluidsAndDrivetrain: [ { interval: "80,000 km", timeLimit: "6 years", task: "Manual Gearbox Oil", details: "Drain and refill the manual transmission.", parts: ["1.5L 75W-80 GL-4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "ZF 6HP Automatic Service", details: "Drain fluid, replace plastic oil pan/filter assembly, and refill.", parts: ["9.0L ZF Lifeguard 6", "ZF Pan/Filter"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Rear Differential Oil", details: "Extract and refill the open rear differential.", parts: ["0.8L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 Low Viscosity fluid.", parts: ["1.0L DOT 4 LV"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Power Steering Fluid", details: "Flush CHF 11S fluid from the reservoir and rack.", parts: ["1.0L CHF 11S"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "40 EUR" } ],
          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Frequent changes are absolutely crucial to keep VANOS solenoids and timing chain tensioners clean.", parts: ["4.25L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Inline filter replacement under the vehicle.", parts: ["Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
          ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently. The extreme lean-burn operation destroys spark plug electrodes rapidly.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to protect the NOX catalytic converter.", parts: ["4x Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "Physically clean carbon buildup from intake valves. Critical for direct-injected N43 engines.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "VANOS Solenoid Clean/Replace", details: "Remove solenoids, clean with brake cleaner, or replace if heavily sludged.", parts: ["Solenoids", "O-Rings"], importance: "High", laborDifficulty: "Easy", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Valve Cover Gasket", details: "Replace brittle rubber gasket to stop oil burning on the exhaust.", parts: ["VCG Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" } ],
          preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "120,000 km", timeLimit: "8 years", task: "Strut Top Mounts", details: "Replace collapsed rubber mounts.", parts: ["Mounts & Bearings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Sway Bar Links", details: "Cure clunking over bumps.", parts: ["Links"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "60 EUR" } ],
          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "120,000 km", timeLimit: "8 years", task: "Water Pump & Thermostat", details: "Proactive replacement of the mechanical pump before bearings fail.", parts: ["Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
          engineMechanical: [ { interval: "150,000 km", timeLimit: "10 years", task: "Complete Timing Chain Service", details: "CRITICAL: The entire chain, guides, and sprockets must be proactively replaced to prevent the plastic guides from shattering into the oil pan.", parts: ["Chain Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "800 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Vacuum Pump Reseal", details: "Replace the O-rings on the rear vacuum pump to stop oil leaking onto the exhaust.", parts: ["Seal Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ]
