        engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Exceptionally lightweight, optimizing the 50:50 weight distribution of the 1 Series chassis.", crankshaft: "Cast Iron, supported by 5 main bearings, optimized for low rotational mass.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "110A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with low-friction skirts.", wristPinDiameter: "20 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "56.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the 10.5:1 compression ratio.", intakePortFlow: "High-velocity ports integrated with the Valvetronic system. The intake valves act directly as the engine's throttle, varying lift from 0.3mm to 9.7mm for extreme efficiency.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust camshafts, plus continuous Valvetronic lift control.", lifterType: "Hydraulic lifters with intermediate levers for Valvetronic.", specialFeature: "Valvetronic eliminates the need for a traditional throttle body during normal operation, severely reducing pumping losses." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "105°C Map-controlled electronic thermostat for extreme thermal efficiency.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Multi-Point EFI Port Injection.", maxPressure: "3.5 Bar static base pressure.", injectors: "4x Bosch EV6 injectors." }, tuningLimits: { maxSafeTorqueStock: "250 Nm.", maxSafePowerStock: "200 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Timing Chain Guides, Valve Stem Seals, Valvetronic Motor." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch ME9.2." } },
