          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-01 synthetic strictly. Critical to keep the VANOS solenoids and Valvetronic system clean.", parts: ["6.5L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "95 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Fuel Filter", details: "Integrated into the fuel pump assembly; replace if fuel pressure drops.", parts: ["Filter Assembly"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
          ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "6 years", task: "Spark Plugs", details: "Replace to prevent misfires and maintain peak engine smoothness.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs.", parts: ["6x Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "180 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "VANOS Solenoid Clean", details: "Remove solenoids, clean with brake cleaner, or replace if heavily sludged.", parts: ["Solenoids", "O-Rings"], importance: "High", laborDifficulty: "Easy", estimatedCost: "150 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket", details: "CRITICAL: Proactively replace to prevent massive oil leaks onto the belt.", parts: ["Gaskets", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Gasket", details: "Replace brittle rubber gasket and Valvetronic sensor seals.", parts: ["VCG Kit", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "200 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace to prevent belt snapping and engine ingestion.", parts: ["Belt", "Tensioner", "Idlers"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "120,000 km", timeLimit: "10 years", task: "Strut Top Mounts", details: "Replace collapsed rubber mounts.", parts: ["Mounts & Bearings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "7 years", task: "Electric Water Pump & T-Stat", details: "CRITICAL: Proactive replacement before sudden failure leaves you stranded.", parts: ["Pierburg Pump", "Thermostat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant alongside the water pump service.", parts: ["8.5L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
          engineMechanical: [ { interval: "100,000 km", timeLimit: "8 years", task: "DISA Valve Inspection", details: "CRITICAL: Inspect the plastic flaps on both the large and small DISA valves for play. Replace if loose to prevent catastrophic engine ingestion.", parts: ["DISA Valves"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "600 EUR" }, { interval: "250,000 km", timeLimit: "No Limit", task: "Timing Chain Inspection", details: "Listen for rattle on cold start. The N52 chain is highly robust, but guides can wear at extremely high mileage.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ]
