        engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Unlike the N52, the N54 reverted to a heavier, traditional aluminum block (rather than magnesium) to handle the massive cylinder pressures and heat generated by the twin-turbo setup.", crankshaft: "Forged Steel, supported by 7 main bearings, optimized for supreme strength under extreme forced induction loads.", pistonSpeed: "18.3 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with specialized crowns for direct injection. Incredibly thick and durable.", wristPinDiameter: "22 mm.", connectingRodLength: "145 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "56.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.64." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the 10.2:1 compression ratio.", intakePortFlow: "High-velocity tumble ports designed specifically to mix air with the high-pressure fuel spray. Lacks Valvetronic; uses a traditional throttle body and double VANOS.", valveSizes: "Intake: 31.4 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS (Variable Valve Timing) on both intake and exhaust camshafts.", lifterType: "Hydraulic lifters with roller finger followers.", specialFeature: "Direct injection ports directly inside the combustion chamber, making it highly susceptible to carbon buildup." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "97°C Map-controlled electronic thermostat.", oilCooler: "External air-to-oil cooler mounted in the passenger side wheel well." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar generated by the mechanical HPFP.", injectors: "6x Siemens VDO Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "700 Nm.", maxSafePowerStock: "700 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Piezo Injectors, HPFP, Plastic Charge Pipe, Turbo Wastegates." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Siemens MSD80 / MSD81." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan and power of the legendary N54 inline-6.", parts: [ { category: "Piezo Injectors", brand: "Genuine BMW (Index 12)", note: "CRITICAL: The only permanent cure for the N54's catastrophic misfires." }, { category: "High Pressure Fuel Pump", brand: "Genuine BMW", note: "CRITICAL: Replace if long cranking times or limp mode occur." }, { category: "Aluminum Charge Pipe", brand: "VRSF / Evolution Racewerks", note: "CRITICAL: Replaces the exploding factory plastic pipe." }, { category: "Electric Water Pump", brand: "Pierburg / VDO", note: "CRITICAL: Replace proactively every 100k km before it fails." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "CRITICAL: Stops catastrophic oil leaks onto the serpentine belt." }, { category: "Ignition Coils", brand: "Eldor", note: "Upgrade to the latest revision for reliable high-boost performance." }, { category: "Spark Plugs", brand: "NGK 2-Step Colder", note: "Mandatory for tuned vehicles to prevent spark blowout." }, { category: "Valve Cover Kit", brand: "Genuine BMW", note: "Replace the entire plastic cover to cure internal PCV failure." } ] },
