          oilAndFilters: [ { interval: "8,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-01 5W-40 synthetic strictly. The N55 shears oil quickly; frequent changes are vital for turbo and rod bearing life.", parts: ["6.5L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "100 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element or clean aftermarket dual cone intakes.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Fuel Filter", details: "Integrated into the fuel pump assembly; replace if low-pressure fuel drops.", parts: ["Filter Assembly"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
          ignitionAndEngine: [ { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "CRITICAL: Tuned N55s eat spark plugs. Replace frequently and gap appropriately.", parts: ["6x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["6x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "250 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "CRITICAL: Physically clean carbon buildup from intake valves. Completely restores lost airflow.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket", details: "CRITICAL: Proactively replace to prevent massive oil leaks onto the belt. MUST PRIME OIL SYSTEM AFTERWARD.", parts: ["Gaskets", "Alu Bolts"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Assembly", details: "Replace entire plastic valve cover due to failing internal PCV valve.", parts: ["Valve Cover", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace to prevent belt snapping and engine ingestion.", parts: ["Belt", "Tensioner", "Idlers"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "120,000 km", timeLimit: "10 years", task: "Strut Top Mounts", details: "Replace collapsed rubber mounts.", parts: ["Mounts & Bearings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "7 years", task: "Electric Water Pump & T-Stat", details: "CRITICAL: Proactive replacement before sudden failure leaves you stranded.", parts: ["Pierburg Pump", "Thermostat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant alongside the water pump service.", parts: ["8.2L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
          engineMechanical: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Aluminum Charge Pipe Install", details: "CRITICAL: Do not tune the car without replacing the plastic charge pipe.", parts: ["Aluminum Pipe"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "250 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Rod Bearing Preventative Service", details: "Highly recommended for tracked or aggressively tuned vehicles to prevent catastrophic failure.", parts: ["ACL Bearings", "Bolts", "Oil Pan Gasket"], importance: "High", laborDifficulty: "Expert", estimatedCost: "1200 EUR" } ]
