        engineeringData: { blockDesign: "Cast-Iron block with aluminum cylinder head. Incredibly heavy but practically indestructible. The M47 utilizes a traditional front-mounted timing chain system, making it vastly superior in long-term reliability to the newer N47.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features notorious swirl flaps in the intake manifold to increase air velocity at low RPMs.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing. Driven by a highly robust dual-row front-mounted timing chain.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "Integrated high-pressure EGR routing." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "88°C Mechanical. Highly prone to failing open.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC16 Common Rail.", maxPressure: "1600 Bar (CP3 Pump).", injectors: "4x Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Limited primarily by the clutch/DMF).", maxSafePowerStock: "220 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Swirl Flaps, Factory Turbocharger, Dual Mass Flywheel." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC16." } },
