        engineeringData: { blockDesign: "Cast-Iron block with aluminum cylinder head. Incredibly heavy but practically indestructible. The M47 utilizes a traditional front-mounted timing chain system, making it vastly superior in long-term reliability to the newer N47.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features notorious swirl flaps in the intake manifold to increase air velocity at low RPMs.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing. Driven by a highly robust dual-row front-mounted timing chain.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "Integrated high-pressure EGR routing." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "88°C Mechanical. Highly prone to failing open.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC16 Common Rail.", maxPressure: "1600 Bar (CP3 Pump).", injectors: "4x Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Limited primarily by the clutch/DMF).", maxSafePowerStock: "220 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Swirl Flaps, Factory Turbocharger, Dual Mass Flywheel." }, electrical: { coils: "Compression Ignition System", ecu: "Bosch EDC16." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to save the M47 diesel block from its fatal flaws.", parts: [ { category: "Swirl Flap Delete Kit", brand: "Teflon Blanking Plates", note: "CRITICAL: Must remove the factory flaps to prevent engine destruction." }, { category: "Dual Mass Flywheel", brand: "LuK", note: "Replace if a loud metallic clattering is heard at idle." }, { category: "Glow Plugs & Module", brand: "Beru / Bosch", note: "Failed glow plugs will prevent the crucial DPF regeneration cycles." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco / Gates", note: "Replace if rubber shows cracking; prevents belt shredding." }, { category: "PCV Vortex Filter", brand: "Genuine BMW", note: "CRITICAL: Replace the toilet-roll filter to save the turbo seals." }, { category: "Main & EGR Thermostats", brand: "Behr / Mahle", note: "Prone to failing open, ruining fuel economy and DPF regens." }, { category: "Automatic Trans Filter", brand: "ZF", note: "Strict 80k km replacement is mandatory for 6HP longevity." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use OEM quality only; frequent changes protect the turbo." } ] },
