          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Critical for DPF health and extending the life of the turbocharger.", parts: ["5.5L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "PCV Breather Service", details: "Replace the crankcase breather unit to prevent turbo seal blowout.", parts: ["PCV Unit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "4 years", task: "Fuel Filter", details: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" } ],
