          coolingAndHvac: [ { interval: "80,000 km", timeLimit: "Unlimited", task: "Thermostat Replacement", details: "Replace the Main and EGR thermostats proactively to ensure the engine reaches 88C for DPF regens.", parts: ["Main T-Stat", "EGR T-Stat"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
