          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Critical for DPF health and extending the life of the fragile timing chain.", parts: ["5.2L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter", details: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" } ],
          ignitionAndEngine: [ { interval: "80,000 km", timeLimit: "5 years", task: "Glow Plugs & Module", details: "Replace to ensure perfect cold starts and active DPF regens.", parts: ["4x Beru Plugs", "Module"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "DPF Ash Cleaning", details: "Remove DPF and send for professional ash flushing.", parts: ["Exhaust Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "EGR & Intake Clean", details: "Remove intake manifold and clean EGR carbon sludge.", parts: ["Gaskets", "Cleaner"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }, { interval: "150,000 km", timeLimit: "8 years", task: "Vibration Damper Check", details: "Inspect the main crank pulley for rubber cracking. Replace immediately to prevent belt shedding.", parts: ["Corteco Pulley"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" } ],
          preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "120,000 km", timeLimit: "8 years", task: "Strut Top Mounts", details: "Replace collapsed rubber mounts.", parts: ["Mounts & Bearings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Dual Mass Flywheel", details: "Replace clattering DMF; usually done with clutch service.", parts: ["LuK DMF Kit"], importance: "High", laborDifficulty: "Expert", estimatedCost: "800 EUR" } ],
          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Water Pump & Thermostat", details: "Proactive replacement of the mechanical pump before bearings fail.", parts: ["Pump", "Thermostat"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
          engineMechanical: [ { interval: "150,000 km", timeLimit: "10 years", task: "Timing Chain Replacement", details: "CRITICAL: Engine must be removed. Proactively replace rear-mounted toothed belt, tensioner, and guides.", parts: ["Timing Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500 EUR" }, { interval: "200,000 km", timeLimit: "Unlimited", task: "Injector Seals", details: "Replace copper crush washers to prevent combustion blow-by.", parts: ["Copper Seals"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Swirl Flap Delete", details: "Install blanking plates in the intake manifold to prevent ingestion.", parts: ["Blanking Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "100 EUR" } ]
