    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. The N13 shears oil quickly; frequent changes protect the timing chain and turbo.", parts: ["4.2L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
