  engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Co-developed with PSA Peugeot Citroën (known as the Prince engine family). Compact, lightweight design specifically optimized for fuel efficiency and rapid turbo spool.", crankshaft: "Cast Iron, supported by 5 main bearings.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy tailored for direct injection.", wristPinDiameter: "20 mm.", connectingRodLength: "138 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.61." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 10.5:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's Valvetronic system to control intake valve lift directly, eliminating throttle body pumping losses.", valveSizes: "Intake: 28.5 mm / Exhaust: 26.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "Direct injection ports bypass the intake valves, leading to inevitable carbon buildup." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "105°C Electronic map-controlled.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "350 Nm.", maxSafePowerStock: "240 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Timing Chain, Plastic Charge Pipe, HPFP." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.4." } },
