  engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. The N20 was designed to replace the naturally aspirated inline-6 N52, offering similar peak power but vastly superior low-end torque and fuel efficiency.", crankshaft: "Cast Iron, supported by 5 main bearings, utilizing balance shafts to reduce inherent 4-cylinder vibrations.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "170A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy tailored for direct injection.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 10.0:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's Valvetronic system to control intake valve lift directly, eliminating throttle body pumping losses.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "Direct injection ports bypass the intake valves, leading to inevitable carbon buildup." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump. Chain-driven (infamous for failure on early models).", thermostatOpening: "108°C Electronic map-controlled.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "420 Nm.", maxSafePowerStock: "300 hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Timing Chain, Connecting Rods (under low RPM torque spikes), Plastic Charge Pipe." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.9." } },
