  engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. Part of the highly successful modular B-series family, featuring incredible structural rigidity compared to older open-deck designs.", crankshaft: "Forged Steel, supported by 5 main bearings.", pistonSpeed: "14.2 m/s @ 6000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy. The 125i uses pistons with a lower 10.2:1 compression ratio (compared to the 120i's 11.0:1), making it significantly safer and more receptive to extreme boost pressures.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 10.2:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's 4th Generation Valvetronic system integrated directly into the cylinder head, controlling intake valve lift to eliminate throttle body pumping losses.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space and improve pedestrian safety." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "105°C Electronic map-controlled Heat Management Module.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar.", injectors: "4x Bosch Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm.", maxSafePowerStock: "380 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Plastic Charge Pipe, Heat Management Module, Factory Turbo limits." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.G." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan of the B48 engine.", parts: [ { category: "Coolant Vent Line", brand: "Genuine BMW / Silicone", note: "CRITICAL: Plastic line snaps and dumps coolant; upgrade to silicone." }, { category: "Water Pump Assembly", brand: "Genuine BMW / INA", note: "Plastic housing cracks over time; replace proactively if weeping coolant." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Mandatory upgrade before applying any ECU tunes." }, { category: "Spark Plugs", brand: "NGK Laser Iridium", note: "Must be replaced strictly every 40k km on tuned engines." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Upgrade to latest revisions to prevent boost misfires." }, { category: "Valve Cover PCV Membrane", brand: "Vaico", note: "Fixes whistling PCV failure without replacing the entire expensive cover." }, { category: "Serpentine Belt", brand: "Continental", note: "Replace if squeaking or showing signs of cracking." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use exclusively OEM quality to protect the delicate VANOS system." } ] },
