  sisterModels: [ { name: "MINI Cooper (F56)", note: "Utilizes the exact same transverse B38A15A 1.5L 3-cylinder engine. The B-series modular architecture and FWD layout marked a massive shift for the 1 Series, completely aligning its underpinnings with the MINI lineup." }, { name: "BMW 2 Series Active Tourer (F45)", note: "Shares the exact front-wheel drive platform (UKL2) and transverse B38 engine layout as the F40 1 Series." } ],
  tuningPotential: [
    { stage: "Stage 1", power: "160 - 170 hp", notes: "The B38 responds extremely well to software tuning. A simple ECU flash adds over 50 horsepower, transforming the 116i from a lethargic city car into a genuinely brisk, torque-rich daily driver. The Twin-Scroll turbo handles this increase effortlessly.", zeroToHundred: "7.8s", hundredToTwoHundred: "24.5s" },
    { stage: "Stage 2", power: "180 - 190 hp", notes: "Requires a high-flow catless downpipe, aluminum charge pipe, and an upgraded intercooler. Provides a massive surge of torque and aggressive turbo spool sounds, pushing the tiny 3-cylinder to its safe limits.", zeroToHundred: "7.3s", hundredToTwoHundred: "22.0s" },
    { stage: "Stage 3 (Hybrid Turbo)", power: "210 - 230 hp", notes: "Requires a hybrid turbocharger and custom tuning. While physically possible, pushing past 200hp on the B38 is generally not recommended, as the cost vastly outweighs the benefits compared to simply swapping to a 4-cylinder B48-equipped 120i.", zeroToHundred: "6.8s", hundredToTwoHundred: "18.5s" }
  ],
