    { partName: "Cabin Filter", category: "Maintenance", oem: { brand: "BMW Genuine", code: "64319313519", approxPrice: "45 EUR" }, crossRef: { brand: "Mann-Filter", code: "CUK 25 001", approxPrice: "25 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/car-parts/oem/64319313519", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=64319313519" }, note: "Activated carbon." }
