    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-12 FE synthetic strictly. Frequent changes are critical for DPF health and timing chain lubrication.", parts: ["5.0L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "90 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "35 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter", details: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" } ],
